from fastapi import APIRouter, Depends
from sqlalchemy.orm import Session
from app.db import get_db
from fastapi import HTTPException
from app.models import Pedido, Estoque
from app.schemas import PedidoIn, PedidoOut, ItemPedidoOut
from app.services import pedidos

router = APIRouter(tags=["Pedidos"])


@router.post("/pedidos", response_model=PedidoOut, status_code=201)
def criar_pedido(dados: PedidoIn, db: Session = Depends(get_db)):
    """Cria um pedido, valida estoque e abate quantidades."""
    return _pedido_to_out(pedidos.criar(db, dados))


@router.get("/pedidos", response_model=list[PedidoOut])
def listar_pedidos(limit: int = 10, db: Session = Depends(get_db)):
    """Retorna os últimos pedidos (padrão: 10)."""
    return [_pedido_to_out(p) for p in pedidos.listar_ultimos(db, limit)]


@router.get("/pedidos/{pedido_id}", response_model=PedidoOut)
def obter_pedido(pedido_id: int, db: Session = Depends(get_db)):
    """Retorna detalhes de um pedido com seus itens."""
    return _pedido_to_out(pedidos.obter(db, pedido_id))


def _pedido_to_out(pedido) -> PedidoOut:
    return PedidoOut(
        id=pedido.id,
        nome_cliente=pedido.nome_cliente,
        total=pedido.total,
        status=pedido.status,
        criado_em=pedido.criado_em,
        itens=[
            ItemPedidoOut(
                produto_id=item.produto_id,
                produto_nome=item.produto.nome,
                quantidade=item.quantidade,
                preco_unitario=item.preco_unitario,
                subtotal=item.subtotal,
            )
            for item in pedido.itens
        ],
    )



# RASCUNHO do colega (sexta à noite): cancelamento, ERP-142. Não terminei; fiz do jeito do faturas.py.
@router.post("/pedidos/{pedido_id}/cancelar", response_model=PedidoOut)
def cancelar_pedido(pedido_id: int, db: Session = Depends(get_db)):
    pedido = db.query(Pedido).filter(Pedido.id == pedido_id).first()
    if not pedido:
        raise HTTPException(status_code=404, detail="Pedido não encontrado")
    for item in pedido.itens:
        estoque = db.query(Estoque).filter(Estoque.produto_id == item.produto_id).first()
        estoque.quantidade += item.quantidade
    pedido.status = "CANCELADO"
    db.commit()
    return _pedido_to_out(pedido)

"""Erros de negócio dos services. As rotas não os tratam: o main.py os traduz para HTTP."""


class NaoEncontrado(Exception):
    """Recurso inexistente (vira 404)."""


class RegraDeNegocio(Exception):
    """Regra violada (vira 400, ou o status informado, como 409 para conflito de estado)."""

    def __init__(self, detalhe: str, status: int = 400):
        super().__init__(detalhe)
        self.status = status

import os
from contextlib import asynccontextmanager
from fastapi import FastAPI, Request
from fastapi.staticfiles import StaticFiles
from fastapi.responses import FileResponse, JSONResponse
from app.db import engine, SessionLocal, Base
from app.models import Produto, Estoque, Pedido, ItemPedido, Fatura  # noqa: F401
from app.seed import seed_db
from app.routes import produtos, estoque, pedidos, faturas, alertas
from app.services.erros import NaoEncontrado, RegraDeNegocio

STATIC_DIR = os.path.join(os.path.dirname(__file__), "static")


@asynccontextmanager
async def lifespan(app: FastAPI):
    # Criar tabelas e popular dados iniciais
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        seed_db(db)
    finally:
        db.close()
    yield


app = FastAPI(
    title="Mini-ERP Didático",
    description="API de distribuição/vendas para laboratório de aula",
    version="1.0.0",
    lifespan=lifespan,
)

# Os services levantam erros de negócio; aqui eles viram HTTP, no mesmo formato {"detail": ...} do FastAPI.
@app.exception_handler(NaoEncontrado)
def tratar_nao_encontrado(request: Request, erro: NaoEncontrado):
    return JSONResponse(status_code=404, content={"detail": str(erro)})


@app.exception_handler(RegraDeNegocio)
def tratar_regra_de_negocio(request: Request, erro: RegraDeNegocio):
    return JSONResponse(status_code=erro.status, content={"detail": str(erro)})


app.include_router(produtos.router)
app.include_router(estoque.router)
app.include_router(pedidos.router)
app.include_router(faturas.router)
app.include_router(alertas.router)


app.mount("/static", StaticFiles(directory=STATIC_DIR), name="static")


@app.get("/", include_in_schema=False)
def root():
    return FileResponse(os.path.join(STATIC_DIR, "index.html"))


@app.get("/health", tags=["Health"])
def health_check():
    return {"status": "ok", "service": "mini-erp"}

